package com.printflow.identity;
import java.util.*;import java.nio.charset.StandardCharsets;import com.printflow.enquiry.TokenUtil;import org.springframework.stereotype.Service;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;
@Service public class CustomerSetup {
 private final JdbcTemplate db;private final PasswordEncoder passwords;private final CustomerMail mail;
 public CustomerSetup(JdbcTemplate db,PasswordEncoder passwords,CustomerMail mail){this.db=db;this.passwords=passwords;this.mail=mail;}
 /** Existing passwords, verified identities and administrator-disabled accounts are never reset here. */
 @Transactional public String prepare(UUID enquiry){var e=db.queryForMap("select email,customer_name,phone,customer_user_id from enquiries where id=? for update",enquiry);String email=e.get("email").toString().trim().toLowerCase(Locale.ROOT);if(email.length()>140)return "Sign in with your existing customer account or contact the team for account setup.";
  if(e.get("customer_user_id")!=null){var linked=db.queryForList("select username from staff_users where id=? and role='CUSTOMER'",e.get("customer_user_id"));if(linked.isEmpty()||!email.equalsIgnoreCase(linked.getFirst().get("username").toString()))return "Access remains with the existing linked customer account. Contact the team for help; no account or password was changed.";}
  String temporary=TokenUtil.newToken();UUID proposed=UUID.randomUUID();int created=db.update("insert into staff_users(id,username,password_hash,role,enabled,must_change_password) values(?,?,?,'CUSTOMER',true,true) on conflict(username) do nothing",proposed,email,passwords.encode(temporary));
  if(created==1)db.update("insert into customer_profiles(user_id,name,phone,privacy_version,setup_pending,consent_at,temporary_password_expires_at) values(?,?,?,'PENDING_SETUP',true,null,now()+interval '1 day')",proposed,e.get("customer_name"),e.get("phone"));
  var users=db.queryForList("select u.id,u.enabled,p.email_verified,p.setup_pending,p.verification_binding from staff_users u join customer_profiles p on p.user_id=u.id where u.username=? and u.role='CUSTOMER' for update of u",email);if(users.isEmpty())return "Contact the team for help accessing the customer workspace.";var user=users.getFirst();UUID id=(UUID)user.get("id");
  if(e.get("customer_user_id")!=null&&!id.equals(e.get("customer_user_id")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Customer ownership changed; review before sending");
  if(Boolean.TRUE.equals(user.get("email_verified"))&&Boolean.TRUE.equals(user.get("enabled"))){db.update("update enquiries set customer_user_id=? where id=?",id,enquiry);return "Your existing account is linked. Sign in using your current password; no password has been changed.";}
  if(!Boolean.TRUE.equals(user.get("setup_pending"))){
   if(!Boolean.TRUE.equals(user.get("email_verified"))&&user.get("verification_binding")==null){
    db.update("update enquiries set customer_user_id=? where id=?",id,enquiry);
    String verify=TokenUtil.newToken();var candidates=db.queryForList("select candidate_password_hash from identity_tokens where user_id=? and purpose='VERIFY' order by expires_at desc limit 1",id);String candidate=candidates.isEmpty()?null:(String)candidates.getFirst().get("candidate_password_hash");db.update("update identity_tokens set used_at=now() where user_id=? and purpose='VERIFY' and used_at is null",id);db.update("update mail_outbox set payload=null,state='SUPERSEDED' where user_id=? and kind='VERIFY' and state='PENDING'",id);db.update("insert into identity_tokens(digest,user_id,purpose,expires_at,candidate_password_hash) values(?,?,'VERIFY',now()+interval '30 minutes',?)",TokenUtil.sha256(verify),id,candidate);
    return "Username: "+email+"\nYou already signed up, but your email is not verified. Your password has not been changed. Verify using this fresh link, then sign in with the password you chose:\n"+mail.publicBase()+"/customer?mode=verify#token="+verify;
   }
   return "Username: "+email+"\nUse your existing sign-in or verification/recovery options. Contact the team if your account is disabled.";
  }
  db.update("update enquiries set customer_user_id=? where id=?",id,enquiry);String token=TokenUtil.newToken();db.update("insert into customer_setup_invites(digest,user_id,enquiry_id,expires_at) values(?,?,?,now()+interval '1 day')",TokenUtil.sha256(token),id,enquiry);
  return "Username: "+email+(created==1?"\nTemporary password: "+temporary+"\nThis password expires in 24 hours and must be changed on first sign-in. Sign in at "+mail.publicBase()+"/customer, or use the setup link below.":"\nYour existing password is unchanged. Use the account setup link below if you have not finished activation.")+"\nChoose your password and confirm the privacy notice using this private, single-use link (valid for 24 hours):\n"+mail.publicBase()+"/customer?mode=setup#token="+token+"\nDo not forward this link. We never email passwords.";
 }
 @Transactional public void finish(String token,String password,boolean consent,String privacy){if(!consent||!CustomerIdentityController.PRIVACY.equals(privacy)||password.length()<14||password.getBytes(StandardCharsets.UTF_8).length>72)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose a password of 14 to 72 UTF-8 bytes and accept the current privacy notice");
  var candidates=db.queryForList("select user_id from customer_setup_invites where digest=? and used_at is null and expires_at>now()",TokenUtil.sha256(token));if(candidates.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Setup link is invalid, expired or used");UUID user=(UUID)candidates.getFirst().get("user_id");var accounts=db.queryForList("select u.id from staff_users u join customer_profiles p on p.user_id=u.id where u.id=? and u.role='CUSTOMER' and p.setup_pending and not p.email_verified for update of u",user);if(accounts.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Account is already set up or unavailable");
  if(db.update("update customer_setup_invites set used_at=now() where digest=? and used_at is null and expires_at>now()",TokenUtil.sha256(token))!=1)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Setup link changed");
  db.update("update staff_users set password_hash=?,enabled=true,must_change_password=false,auth_version=auth_version+1 where id=?",passwords.encode(password),user);db.update("update customer_profiles set email_verified=true,setup_pending=false,temporary_password_expires_at=null,privacy_version=?,consent_at=now(),verification_binding=null where user_id=?",privacy,user);db.update("update customer_setup_invites set used_at=now() where user_id=? and used_at is null",user);db.update("update identity_tokens set used_at=now() where user_id=? and used_at is null",user);
 }
 @Transactional public void activate(StaffPrincipal actor,String chosen,boolean consent,String privacy){
  if(!actor.role().equals("CUSTOMER")||!actor.mustChangePassword())throw new ResponseStatusException(HttpStatus.FORBIDDEN);
  if(!consent||!CustomerIdentityController.PRIVACY.equals(privacy)||chosen.length()<14||chosen.getBytes(StandardCharsets.UTF_8).length>72)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose a password of at least 14 characters and accept the privacy notice");
  var users=db.queryForList("select u.password_hash from staff_users u join customer_profiles p on p.user_id=u.id where u.id=? and u.enabled and u.must_change_password and p.setup_pending and p.temporary_password_expires_at>now() for update of u",actor.id());if(users.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Temporary access expired; use the setup link in your email");if(passwords.matches(chosen,users.getFirst().get("password_hash").toString()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose a new password different from the temporary password");
  db.update("update staff_users set password_hash=?,must_change_password=false,auth_version=auth_version+1 where id=?",passwords.encode(chosen),actor.id());db.update("update customer_profiles set email_verified=true,setup_pending=false,temporary_password_expires_at=null,privacy_version=?,consent_at=now(),verification_binding=null where user_id=?",privacy,actor.id());db.update("update customer_setup_invites set used_at=now() where user_id=? and used_at is null",actor.id());db.update("update identity_tokens set used_at=now(),candidate_password_hash=null where user_id=? and used_at is null",actor.id());
 }

}
